import React, { useState, useEffect, useRef } from 'react';
import './NotesWidget.css';

// Hidden Notepad Access Button Component
export const HiddenNotepadAccessButton = ({ onOpen }) => {
  return (
    <div className="hidden-notepad-access" id="hiddenNotepadAccess" title="Click to open Notepad">
      <div className="notepad-access-icon" onClick={onOpen}>
        <i className="fas fa-sticky-note"></i>
      </div>
    </div>
  );
};

const NotesWidget = ({ onClose }) => {
  // State management
  const [notes, setNotes] = useState([]);
  const [filteredNotes, setFilteredNotes] = useState([]);
  const [currentTab, setCurrentTab] = useState('view');
  const [searchTerm, setSearchTerm] = useState('');
  const [newNoteContent, setNewNoteContent] = useState('');
  const [notification, setNotification] = useState({ show: false, type: '', message: '' });
  const [dualPaneView, setDualPaneView] = useState(false);
  const [currentAISummary, setCurrentAISummary] = useState('');
  const [aiSummaries, setAISummaries] = useState([]);
  const [currentAISummaryMeta, setCurrentAISummaryMeta] = useState(null);

  const textareaRef = useRef(null);
  const notificationTimeoutRef = useRef(null);

  // Load notes from localStorage on component mount
  useEffect(() => {
    loadNotes();
  }, []);

  // Filter notes whenever notes or search term changes
  useEffect(() => {
    const filtered = searchTerm
      ? notes.filter(note =>
          note.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
          note.dateCreated.toLowerCase().includes(searchTerm.toLowerCase())
        )
      : notes;
    setFilteredNotes(filtered);
  }, [notes, searchTerm]);

  const loadNotes = () => {
    try {
      const savedNotes = localStorage.getItem('notepad_notes');
      if (savedNotes) {
        const parsedNotes = JSON.parse(savedNotes);
        setNotes(parsedNotes);
        setFilteredNotes(parsedNotes);
      } else {
        setNotes([]);
        setFilteredNotes([]);
      }
    } catch (error) {
      console.error('Error loading notes:', error);
      setNotes([]);
      setFilteredNotes([]);
      showNotification('Error loading notes', 'error');
    }
  };

  const saveNotes = async () => {
    try {
      localStorage.setItem('notepad_notes', JSON.stringify(notes));
      // Try to save to backend as well
      try {
        const response = await fetch('http://127.0.0.1:5001/api/notepad/save', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            notes: notes,
            lastSaved: new Date().toISOString(),
            totalNotes: notes.length,
            saveEnvironment: 'react_frontend'
          })
        });

        if (!response.ok) {
          console.warn('Backend save failed, using local storage');
        }
      } catch (backendError) {
        console.warn('Backend not available, using local storage');
      }
    } catch (error) {
      console.error('Error saving notes:', error);
      showNotification('Error saving notes', 'error');
      return false;
    }
    return true;
  };

  const addNote = async () => {
    if (!newNoteContent.trim()) {
      showNotification('Please write something before saving!', 'warning');
      return;
    }

    showNotification('Saving note...', 'info', 2000);

    const now = new Date();
    const newNote = {
      id: Date.now().toString(),
      content: newNoteContent,
      timestamp: now.toISOString(),
      dateCreated: now.toLocaleString(),
      preview: newNoteContent.substring(0, 120) + (newNoteContent.length > 120 ? '...' : ''),
      wordCount: newNoteContent.split(/\s+/).filter(word => word.length > 0).length,
    };

    const updatedNotes = [newNote, ...notes];
    setNotes(updatedNotes);

    const saveSuccess = await saveNotes();

    if (saveSuccess) {
      setNewNoteContent('');
      setCurrentTab('view');
      showNotification(`Note saved successfully! Total notes: ${updatedNotes.length}`, 'success');
    } else {
      showNotification('Failed to save note', 'error');
    }
  };

  const deleteNote = (noteId) => {
    if (window.confirm('Are you sure you want to delete this note?')) {
      const updatedNotes = notes.filter(note => note.id !== noteId);
      setNotes(updatedNotes);
      saveNotes();
      showNotification('Note deleted successfully', 'success');
    }
  };

  const editNote = (noteId) => {
    const note = notes.find(n => n.id === noteId);
    if (note) {
      setNewNoteContent(note.content);
      // Remove the note from the list
      const updatedNotes = notes.filter(n => n.id !== noteId);
      setNotes(updatedNotes);
      setCurrentTab('add');
      showNotification('Note loaded for editing', 'info');
    }
  };

  const copyNote = async (noteId) => {
    const note = notes.find(n => n.id === noteId);
    if (note) {
      try {
        await navigator.clipboard.writeText(note.content);
        showNotification('Note copied to clipboard!', 'success');
      } catch (err) {
        console.error('Failed to copy text:', err);
        showNotification('Failed to copy note', 'error');
      }
    }
  };

  const clearAllNotes = () => {
    if (notes.length === 0) {
      showNotification('No notes to clear!', 'warning');
      return;
    }

    if (window.confirm(`Are you sure you want to delete all ${notes.length} notes? This action cannot be undone.`)) {
      setNotes([]);
      setFilteredNotes([]);
      saveNotes();
      showNotification(`All ${notes.length} notes cleared successfully`, 'success');
    }
  };

  const exportNotes = () => {
    if (notes.length === 0) {
      showNotification('No notes to export! Please create some notes first.', 'warning');
      return;
    }

    try {
      const now = new Date();
      const exportData = {
        exportInfo: {
          exportDate: now.toISOString(),
          exportDateFormatted: now.toLocaleString(),
          totalNotes: notes.length,
          exportedBy: 'Astra AI Notepad Manager',
          version: '1.0',
          storageType: 'react_frontend'
        },
        notes: notes,
        statistics: {
          totalWords: notes.reduce((sum, note) => sum + (note.wordCount || 0), 0),
          averageWordsPerNote: Math.round(notes.reduce((sum, note) => sum + (note.wordCount || 0), 0) / notes.length),
          oldestNote: notes.length > 0 ? notes[notes.length - 1].dateCreated : null,
          newestNote: notes.length > 0 ? notes[0].dateCreated : null
        }
      };

      const dataStr = JSON.stringify(exportData, null, 2);
      const dataBlob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(dataBlob);

      const link = document.createElement('a');
      link.href = url;
      link.download = `notepad-export-${now.toISOString().split('T')[0]}-${now.getHours()}${now.getMinutes().toString().padStart(2, '0')}.json`;

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      URL.revokeObjectURL(url);
      showNotification(`${notes.length} notes exported to JSON file successfully!`, 'success');
    } catch (error) {
      console.error('Export failed:', error);
      showNotification('Export failed. Please try again.', 'error');
    }
  };

  const exportNotesToTxt = () => {
    if (notes.length === 0) {
      showNotification('No notes to export! Please create some notes first.', 'warning');
      return;
    }

    try {
      const txtContent = notes.map(note => {
        return `Note - ${note.dateCreated}\n${note.content}\n\n${'='.repeat(50)}\n\n`;
      }).join('');

      const dataBlob = new Blob([txtContent], { type: 'text/plain' });
      const url = URL.createObjectURL(dataBlob);

      const link = document.createElement('a');
      link.href = url;
      link.download = `notepad-export-${new Date().toISOString().split('T')[0]}.txt`;

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      URL.revokeObjectURL(url);
      showNotification(`${notes.length} notes exported to TXT file successfully!`, 'success');
    } catch (error) {
      console.error('TXT export failed:', error);
      showNotification('TXT export failed. Please try again.', 'error');
    }
  };

  const importTextFile = (event) => {
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.txt';

    fileInput.onchange = (e) => {
      const file = e.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const content = e.target.result;
          if (content.trim()) {
            const now = new Date();
            const newNote = {
              id: Date.now().toString(),
              content: content,
              timestamp: now.toISOString(),
              dateCreated: now.toLocaleString(),
              preview: content.substring(0, 120) + (content.length > 120 ? '...' : ''),
              wordCount: content.split(/\s+/).filter(word => word.length > 0).length,
            };

            const updatedNotes = [newNote, ...notes];
            setNotes(updatedNotes);

            const saveSuccess = await saveNotes();
            if (saveSuccess) {
              showNotification(`Imported note added successfully! Total notes: ${updatedNotes.length}`, 'success');
            } else {
              showNotification('Failed to save imported note', 'error');
            }
          }
        } catch (error) {
          console.error('Error importing file:', error);
          showNotification('Error importing file', 'error');
        }
      };
      reader.readAsText(file);
    };

    fileInput.click();
  };

  const showNotification = (message, type = 'info', duration = 4000) => {
    // Clear any existing timeout
    if (notificationTimeoutRef.current) {
      clearTimeout(notificationTimeoutRef.current);
    }

    setNotification({ show: true, type, message });

    // Auto-hide notification after specified duration
    notificationTimeoutRef.current = setTimeout(() => {
      setNotification({ show: false, type: '', message: '' });
    }, duration);
  };

  const hideNotification = () => {
    if (notificationTimeoutRef.current) {
      clearTimeout(notificationTimeoutRef.current);
    }
    setNotification({ show: false, type: '', message: '' });
  };

  const countWords = (text) => {
    return text.trim() ? text.trim().split(/\s+/).filter(word => word.length > 0).length : 0;
  };

  const countLines = (text) => {
    return text.split('\n').length;
  };

  const updateCharacterCount = () => {
    if (textareaRef.current) {
      const text = textareaRef.current.value;
      const words = countWords(text);
      const lines = countLines(text);
      return `${text.length} characters • ${words} words • ${lines} lines`;
    }
    return '0 characters • 0 words • 0 lines';
  };

  const summarizeSingleNote = async (noteId) => {
    const note = notes.find(n => n.id === noteId);
    if (!note) {
      showNotification('Note not found. Please try again.', 'error');
      return;
    }

    try {
      showNotification('Generating AI summary...', 'info');

      // Create a prompt specifically for this note
      const noteText = `Note (${note.dateCreated}): ${note.content}`;
      const summarizationPrompt = `Please provide a comprehensive summary of the following note.
      Focus on the key points, insights, and any action items.
      Make the summary clear, concise, and well-structured.

      ${noteText}`;

      // Call the API
      const response = await fetch('http://127.0.0.1:5001/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: summarizationPrompt,
          session_id: 'notepad-summary-' + Date.now()
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data && data.response) {
        setCurrentAISummary(data.response);
        setDualPaneView(true);
        showNotification('AI summary generated successfully', 'success');
      } else {
        throw new Error('No response from AI service');
      }
    } catch (error) {
      console.error('AI Summarization error:', error);
      showNotification('AI Summarization failed. Please make sure the Nova AI service is running and try again.', 'error');
    }
  };

  const saveAISummary = async () => {
    if (!currentAISummary.trim()) {
      showNotification('No AI summary to save', 'warning');
      return;
    }

    const now = new Date();
    const aiSummary = {
      id: `ai-${Date.now()}`,
      content: currentAISummary,
      timestamp: now.toISOString(),
      dateCreated: now.toLocaleString(),
      sourceType: 'ai-generated',
    };

    const updatedSummaries = [aiSummary, ...aiSummaries];
    setAISummaries(updatedSummaries);

    // Save to localStorage
    localStorage.setItem('ai_summaries', JSON.stringify(updatedSummaries));

    showNotification('AI summary saved successfully', 'success');
    setDualPaneView(false);
  };

  const copyAISummary = async () => {
    if (!currentAISummary.trim()) {
      showNotification('No AI summary to copy', 'warning');
      return;
    }

    try {
      await navigator.clipboard.writeText(currentAISummary);
      showNotification('AI summary copied to clipboard!', 'success');
    } catch (err) {
      console.error('Failed to copy text:', err);
      showNotification('Failed to copy AI summary', 'error');
    }
  };

  const hideDualPaneView = () => {
    setDualPaneView(false);
    setCurrentAISummary('');
  };

  return (
    <div className="notes-widget">
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>

      {/* Notification System */}
      <div className={`notes-notification ${notification.show ? 'show' : ''} ${notification.type}`}>
        <div className="notification-content">
          <div className="notification-icon">
            {notification.type === 'success' && <i className="fas fa-check"></i>}
            {notification.type === 'error' && <i className="fas fa-exclamation-circle"></i>}
            {notification.type === 'warning' && <i className="fas fa-exclamation-triangle"></i>}
            {notification.type === 'info' && <i className="fas fa-info-circle"></i>}
          </div>
          <div className="notification-message">{notification.message}</div>
          <button className="notification-close" onClick={hideNotification}>
            <i className="fas fa-times"></i>
          </button>
        </div>
        <div className="notification-progress" id="notificationProgress"></div>
      </div>

      {/* Header */}
      <div className="notes-header">
        <div className="notes-title">
          <div className="notes-logo"><i className="fa-solid fa-book-open"></i></div>
          <div className="notes-brand">Notepad Manager</div>
        </div>
        <div className="notes-status">
          <div className="notes-status-indicator"></div>
          <span>Active</span>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="notes-nav">
        <div
          className={`notes-nav-tab ${currentTab === 'view' ? 'active' : ''}`}
          onClick={() => setCurrentTab('view')}
        >
          View Notes
        </div>
        <div
          className={`notes-nav-tab ${currentTab === 'add' ? 'active' : ''}`}
          onClick={() => setCurrentTab('add')}
        >
          Add Note
        </div>
        <div
          className={`notes-nav-tab ${currentTab === 'ai-summaries' ? 'active' : ''}`}
          onClick={() => setCurrentTab('ai-summaries')}
        >
          <i className="fa-solid fa-brain"></i> AI Summaries
        </div>
      </div>

      {/* Search Bar - Only show in view tab */}
      {currentTab === 'view' && (
        <div className="notes-search">
          <input
            type="text"
            className="notes-search-input"
            placeholder="Search notes..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Main Content Area */}
      {dualPaneView ? (
        <div className="dual-pane-view" id="notepadDualPane">
          <div className="dual-pane-header">
            <div className="dual-pane-title">
              <i className="fa-solid fa-brain"></i> AI Summary View
            </div>
            <button className="dual-pane-close" onClick={hideDualPaneView} title="Close Summary View">
              <i className="fa-solid fa-times"></i>
            </button>
          </div>
          <div className="dual-pane-content">
            <div className="dual-pane-left">
              <div className="pane-label">
                <i className="fa-solid fa-sticky-note"></i> Your Notes
              </div>
              <div className="pane-content" id="dualPaneOriginalNotes">
                {notes.length > 0 ? (
                  notes.map(note => (
                    <div key={note.id} style={{marginBottom: '16px', padding: '12px', background: 'rgba(0, 150, 255, 0.05)', border: '1px solid rgba(0, 150, 255, 0.2)', borderRadius: '6px'}}>
                      <div style={{fontSize: '10px', color: 'rgba(0, 200, 255, 0.8)', marginBottom: '6px', fontWeight: '600'}}>
                        {note.dateCreated} • ID: {note.id.slice(-4)}
                      </div>
                      <div style={{whiteSpace: 'pre-wrap', lineHeight: '1.4'}}>
                        {note.content}
                      </div>
                    </div>
                  ))
                ) : (
                  <div style={{textAlign: 'center', color: 'rgba(255, 255, 255, 0.6)', padding: '20px'}}>
                    <i className="fas fa-sticky-note" style={{fontSize: '24px', marginBottom: '8px'}}></i>
                    <p>No notes to display</p>
                  </div>
                )}
              </div>
            </div>
            <div className="dual-pane-divider"></div>
            <div className="dual-pane-right">
              <div className="pane-label">
                <i className="fa-solid fa-magic-wand-sparkles"></i> AI Summary
                <div className="ai-summary-controls">
                  <button className="ai-summary-btn copy-summary-btn" onClick={copyAISummary} title="Copy AI Summary">
                    <i className="fa-solid fa-copy"></i>
                  </button>
                  <button className="ai-summary-btn save-summary-btn" onClick={saveAISummary} title="Save AI Summary">
                    <i className="fa-solid fa-bookmark"></i>
                  </button>
                </div>
              </div>
              <div className="pane-content" id="dualPaneAISummary">
                <div style={{whiteSpace: 'pre-wrap', lineHeight: '1.5', marginBottom: '12px'}}>
                  {currentAISummary}
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <>
          {/* View Tab Content */}
          {currentTab === 'view' && (
            <div className="notes-content-area" id="notesContentArea">
              {filteredNotes.length === 0 ? (
                <div className="notes-empty">
                  <i className="fas fa-sticky-note"></i>
                  <h3>No Notes Yet</h3>
                  <p>Click "Add Note" to create your first note!</p>
                </div>
              ) : (
                filteredNotes.map(note => (
                  <div key={note.id} className="notes-item">
                    <div className="notes-meta">
                      <span className="notes-id">ID: {note.id.slice(-4)}</span>
                      <span className="notes-time">{note.dateCreated}</span>
                    </div>
                    <div className="notes-preview">{note.preview}</div>
                    <div className="notes-actions">
                      <button className="notes-action-btn" onClick={() => {
                        const noteToView = notes.find(n => n.id === note.id);
                        if (noteToView) {
                          alert(`Note Content:\n\n${noteToView.content}`);
                        }
                      }}>
                        <i className="fas fa-eye"></i> View
                      </button>
                      <button className="notes-action-btn" onClick={() => editNote(note.id)}>
                        <i className="fas fa-edit"></i> Edit
                      </button>
                      <button className="notes-action-btn" onClick={() => copyNote(note.id)}>
                        <i className="fas fa-copy"></i> Copy
                      </button>
                      <button className="notes-action-btn summarize-single-btn" onClick={() => summarizeSingleNote(note.id)}>
                        <i className="fas fa-robot"></i> AI Summarize
                      </button>
                      <button className="notes-action-btn danger" onClick={() => deleteNote(note.id)}>
                        <i className="fas fa-trash"></i> Delete
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {/* Add Note Tab */}
          {currentTab === 'add' && (
            <div className="add-note-form" id="notepadAddNoteForm">
              <textarea
                ref={textareaRef}
                className="add-note-textarea"
                value={newNoteContent}
                onChange={(e) => setNewNoteContent(e.target.value)}
                placeholder="Write your note here... Click anywhere to position cursor and edit text"
                spellCheck="true"
                wrap="soft"
              />
              <div className="add-note-controls">
                <div className="char-count" id="notepadCharCount">
                  {updateCharacterCount()}
                </div>
                <button className="add-note-btn" onClick={addNote}>
                  Save Note
                </button>
              </div>
            </div>
          )}

          {/* AI Summaries Tab */}
          {currentTab === 'ai-summaries' && (
            <div className="notes-ai-summaries-area" id="notepadAISummariesArea">
              <div className="notes-empty">
                <i className="fas fa-brain"></i>
                <h3>AI Summaries</h3>
                <p>Generate summaries of your notes using AI.</p>
              </div>
            </div>
          )}
        </>
      )}

      {/* Footer Controls */}
      <div className="notes-footer">
        <div className="notes-count" id="notepadCount">
          {currentTab !== 'ai-summaries' ? `${filteredNotes.length} note${filteredNotes.length !== 1 ? 's' : ''}` : ''}
        </div>
        <div className="notes-ai-count" id="notepadAICount" style={{display: currentTab === 'ai-summaries' ? 'block' : 'none'}}>
          0 AI summaries
        </div>
        <div className="notes-controls" id="notepadControls" style={{display: currentTab === 'ai-summaries' ? 'none' : 'flex'}}>
          <div className="notes-control-btn import-btn" onClick={importTextFile} title="Import .txt file">
            <i className="fa-solid fa-file-import"></i>
          </div>
          <div className="notes-control-btn export-txt-btn" onClick={exportNotesToTxt} title="Export as .txt file">
            <i className="fa-solid fa-file-text"></i>
          </div>
          <div className="notes-control-btn export-btn" onClick={exportNotes} title="Export all notes to JSON file">
            <i className="fa-solid fa-download"></i>
          </div>
          <div className="notes-control-btn" onClick={clearAllNotes} title="Clear All Notes">
            <i className="fa-solid fa-trash"></i>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NotesWidget;
